theorem size_of_intersection_eq_two : 
    let I : Set ℝ := Set.Icc (0 : ℝ) π
    let f : ℝ → ℝ := fun x => Real.sin ((π / 2) * Real.cos x)
    let g : ℝ → ℝ := fun x => Real.cos ((π / 2) * Real.sin x)
    in Finset.card (I ∩ {x | f x = g x}).toFinite.toFinset = 2 := sorry

theorem max_distance_eq_two_sqrt_twenty_one : 
    let A : Set ℂ := {z | z ^ 3 - 8 = 0}
    let B : Set ℂ := {z | z ^ 3 - 8 * z ^ 2 - 8 * z + 64 = 0}
    let dist (u v : ℂ) : ℝ := Real.sqrt (((u.re - v.re) ^ 2) + ((u.im - v.im) ^ 2))
    in sSup (Set.image (fun (p : ℂ × ℂ) => dist p.1 p.2) (A ×ˢ B)) = 2 * Real.sqrt 21 := sorry

theorem log_sqrt_identity : 
    let a := (6 : ℝ) 
    let b := (2 : ℝ) 
    let c := (3 : ℝ) 
    let L1 := Real.logb b a 
    let L2 := Real.logb c a 
    let S := Real.sqrt (L1 + L2) in
    S = Real.sqrt (Real.logb b c) + Real.sqrt (Real.logb c b) := sorry
